function localizeKnowledge(code){
 var root=document.getElementById("knowledge-center");if(!root)return;
 var v=KNOWLEDGE[code]||KNOWLEDGE.EN;
 var nodes=[root.querySelector(":scope > div > p"),root.querySelector("h2"),root.querySelector("h2 + p")].concat(Array.from(root.querySelectorAll('a[href$=".html"]')));
 nodes.forEach(function(node,i){if(node&&typeof v[i]==="string"&&node.textContent!==v[i])node.textContent=v[i];if(node&&(code==="AR"||code==="HE"))node.setAttribute("dir","auto");else if(node)node.removeAttribute("dir");});
}

var MCP_LOCALES={"EN":["Connect Poly-Glot from supported MCP clients","These directories list the same production Poly-Glot MCP server. In a compatible MCP client, add the Streamable HTTP URL below, name it Poly-Glot, and approve tool access. No separate server is needed for each directory.","Explore MCP integrations →","1. Choose your MCP client","Open the client's MCP, Connectors, Tools, or Integrations settings.","2. Add the remote server","Paste the Poly-Glot MCP endpoint and save it as Poly-Glot.","3. Approve & use the tools","Allow tool access, then search templates, build prompts, prepare comparisons, and use Poly-Glot's other MCP tools."],"ES":["Conecta Poly-Glot desde clientes MCP compatibles","Estos directorios muestran el mismo servidor MCP de producción de Poly-Glot. En un cliente compatible, añade la URL Streamable HTTP, ponle el nombre Poly-Glot y autoriza el acceso a las herramientas. No necesitas un servidor distinto por directorio.","Explorar integraciones MCP →","1. Elige tu cliente MCP","Abre la configuración de MCP, conectores, herramientas o integraciones del cliente.","2. Añade el servidor remoto","Pega el endpoint MCP y guárdalo como Poly-Glot.","3. Autoriza y usa las herramientas","Autoriza el acceso y busca plantillas, crea prompts, prepara comparaciones y utiliza las demás herramientas MCP."],"FR":["Connectez Poly-Glot aux clients MCP compatibles","Ces annuaires répertorient le même serveur MCP Poly-Glot de production. Dans un client compatible, ajoutez l’URL Streamable HTTP, nommez-le Poly-Glot et autorisez les outils. Aucun serveur distinct n’est nécessaire pour chaque annuaire.","Explorer les intégrations MCP →","1. Choisissez votre client MCP","Ouvrez les paramètres MCP, Connecteurs, Outils ou Intégrations du client.","2. Ajoutez le serveur distant","Collez l’adresse MCP et enregistrez-la sous Poly-Glot.","3. Autorisez et utilisez les outils","Autorisez l’accès, recherchez des modèles, créez des prompts, préparez des comparaisons et utilisez les autres outils MCP."],"DE":["Poly-Glot mit unterstützten MCP-Clients verbinden","Diese Verzeichnisse listen denselben produktiven Poly-Glot-MCP-Server. Füge in einem kompatiblen Client die Streamable-HTTP-URL hinzu, nenne ihn Poly-Glot und erlaube den Werkzeugzugriff. Du brauchst keinen separaten Server pro Verzeichnis.","MCP-Integrationen erkunden →","1. MCP-Client auswählen","Öffne die Einstellungen für MCP, Konnektoren, Werkzeuge oder Integrationen.","2. Remote-Server hinzufügen","Füge den MCP-Endpunkt ein und speichere ihn als Poly-Glot.","3. Tools zulassen und verwenden","Erlaube den Zugriff, suche Vorlagen, erstelle Prompts, bereite Vergleiche vor und nutze weitere MCP-Tools."],"IT":["Connetti Poly-Glot dai client MCP compatibili","Queste directory elencano lo stesso server MCP Poly-Glot di produzione. In un client compatibile, aggiungi l’URL Streamable HTTP, chiamalo Poly-Glot e autorizza gli strumenti. Non serve un server diverso per ogni directory.","Esplora le integrazioni MCP →","1. Scegli il client MCP","Apri le impostazioni MCP, Connettori, Strumenti o Integrazioni del client.","2. Aggiungi il server remoto","Incolla l’endpoint MCP e salvalo come Poly-Glot.","3. Autorizza e usa gli strumenti","Consenti l’accesso, cerca modelli, crea prompt, prepara confronti e usa gli altri strumenti MCP."],"PT":["Conecte o Poly-Glot por clientes MCP compatíveis","Estes diretórios listam o mesmo servidor MCP de produção do Poly-Glot. Em um cliente compatível, adicione a URL Streamable HTTP, nomeie como Poly-Glot e permita acesso às ferramentas. Não é necessário um servidor diferente por diretório.","Explorar integrações MCP →","1. Escolha seu cliente MCP","Abra as configurações de MCP, Conectores, Ferramentas ou Integrações do cliente.","2. Adicione o servidor remoto","Cole o endpoint MCP e salve-o como Poly-Glot.","3. Autorize e use as ferramentas","Permita o acesso, pesquise modelos, crie prompts, prepare comparações e use as demais ferramentas MCP."],"NL":["Verbind Poly-Glot met ondersteunde MCP-clients","Deze gidsen vermelden dezelfde productie-MCP-server van Poly-Glot. Voeg in een compatibele client de Streamable HTTP-URL toe, noem deze Poly-Glot en sta toegang tot tools toe. Per gids is geen aparte server nodig.","MCP-integraties verkennen →","1. Kies je MCP-client","Open de instellingen voor MCP, Connectors, Tools of Integraties.","2. Voeg de externe server toe","Plak het MCP-eindpunt en sla het op als Poly-Glot.","3. Sta de tools toe en gebruik ze","Geef toegang en zoek sjablonen, bouw prompts, bereid vergelijkingen voor en gebruik andere MCP-tools."],"RU":["Подключите Poly-Glot через совместимые MCP-клиенты","Все эти каталоги указывают на один рабочий MCP-сервер Poly-Glot. В совместимом клиенте добавьте адрес Streamable HTTP, назовите подключение Poly-Glot и разрешите доступ к инструментам. Для каждого каталога отдельный сервер не нужен.","Смотреть интеграции MCP →","1. Выберите MCP-клиент","Откройте настройки MCP, подключений, инструментов или интеграций.","2. Добавьте удалённый сервер","Вставьте адрес MCP и сохраните его с именем Poly-Glot.","3. Разрешите доступ к инструментам","Разрешите доступ, ищите шаблоны, создавайте запросы, готовьте сравнения и используйте другие инструменты MCP."],"ZH":["在兼容的 MCP 客户端中连接 Poly-Glot","这些目录指向同一个 Poly-Glot 生产 MCP 服务器。在兼容客户端中添加下方的 Streamable HTTP 地址，命名为 Poly-Glot 并授权工具访问。无需为每个目录部署不同服务器。","探索 MCP 集成 →","1. 选择 MCP 客户端","打开客户端的 MCP、连接器、工具或集成设置。","2. 添加远程服务器","粘贴 MCP 端点并将其保存为 Poly-Glot。","3. 授权并使用工具","授权工具访问，然后搜索模板、构建提示词、准备比较并使用其他 MCP 工具。"],"ZH_TW":["在相容的 MCP 用戶端中連接 Poly-Glot","這些目錄指向同一個 Poly-Glot 正式環境 MCP 伺服器。在相容用戶端中加入下方的 Streamable HTTP 網址，命名為 Poly-Glot 並允許工具存取。無須為各目錄建立不同伺服器。","探索 MCP 整合 →","1. 選擇 MCP 用戶端","開啟用戶端的 MCP、連接器、工具或整合設定。","2. 新增遠端伺服器","貼上 MCP 端點，並儲存為 Poly-Glot。","3. 授權並使用工具","允許工具存取，再搜尋範本、建立提示詞、準備比較並使用其他 MCP 工具。"],"JA":["対応 MCP クライアントから Poly-Glot に接続","各ディレクトリは同じ本番 Poly-Glot MCP サーバーを掲載しています。対応クライアントに下記の Streamable HTTP URL を追加し、Poly-Glot と名付けてツールへのアクセスを許可してください。個別のサーバーは不要です。","MCP 連携を見る →","1. MCP クライアントを選択","クライアントの MCP、コネクタ、ツール、連携設定を開きます。","2. リモートサーバーを追加","MCP エンドポイントを貼り付け、Poly-Glot として保存します。","3. ツールを許可して使用","ツールへのアクセスを許可し、テンプレートの検索、プロンプト作成、比較準備などを行います。"],"KO":["지원되는 MCP 클라이언트에서 Poly-Glot 연결","이 디렉터리들은 동일한 Poly-Glot 운영 MCP 서버를 안내합니다. 호환되는 클라이언트에 아래 Streamable HTTP URL을 추가하고 Poly-Glot으로 이름을 지정한 다음 도구 액세스를 승인하세요. 디렉터리마다 별도의 서버는 필요하지 않습니다.","MCP 통합 살펴보기 →","1. MCP 클라이언트 선택","클라이언트의 MCP, 커넥터, 도구 또는 통합 설정을 여세요.","2. 원격 서버 추가","MCP 엔드포인트를 붙여 넣고 Poly-Glot으로 저장하세요.","3. 도구 승인 및 사용","도구 액세스를 승인한 뒤 템플릿 검색, 프롬프트 작성, 비교 준비 등 MCP 도구를 사용하세요."],"AR":["اربط Poly-Glot بعملاء MCP المتوافقين","تعرض هذه الأدلة خادم Poly-Glot MCP الإنتاجي نفسه. أضف رابط Streamable HTTP أدناه في عميل متوافق، وسمّه Poly-Glot، ثم اسمح بالوصول إلى الأدوات. لا تحتاج إلى خادم مختلف لكل دليل.","استكشف تكاملات MCP →","1. اختر عميل MCP","افتح إعدادات MCP أو الموصلات أو الأدوات أو التكاملات في العميل.","2. أضف الخادم البعيد","الصق عنوان نقطة نهاية MCP واحفظه باسم Poly-Glot.","3. وافق على الأدوات واستخدمها","اسمح بالوصول إلى الأدوات ثم ابحث عن القوالب وأنشئ المطالبات وجهّز المقارنات واستخدم أدوات MCP الأخرى."],"HI":["समर्थित MCP क्लाइंट से Poly-Glot जोड़ें","ये निर्देशिकाएँ एक ही Poly-Glot उत्पादन MCP सर्वर दिखाती हैं। संगत क्लाइंट में नीचे दिया Streamable HTTP URL जोड़ें, नाम Poly-Glot रखें और टूल एक्सेस की अनुमति दें। हर निर्देशिका के लिए अलग सर्वर नहीं चाहिए।","MCP एकीकरण देखें →","1. MCP क्लाइंट चुनें","क्लाइंट की MCP, कनेक्टर, टूल या एकीकरण सेटिंग खोलें।","2. रिमोट सर्वर जोड़ें","MCP एंडपॉइंट पेस्ट करके Poly-Glot नाम से सहेजें।","3. टूल की अनुमति दें और उपयोग करें","एक्सेस की अनुमति देकर टेम्पलेट खोजें, प्रॉम्प्ट बनाएँ, तुलना तैयार करें और अन्य MCP टूल इस्तेमाल करें।"],"BN":["সমর্থিত MCP ক্লায়েন্টে Poly-Glot যুক্ত করুন","এই ডিরেক্টরিগুলো একই Poly-Glot প্রোডাকশন MCP সার্ভারের তালিকা দেখায়। সামঞ্জস্যপূর্ণ ক্লায়েন্টে নিচের Streamable HTTP URL যোগ করুন, নাম দিন Poly-Glot এবং টুল ব্যবহারের অনুমতি দিন। আলাদা সার্ভার দরকার নেই।","MCP ইন্টিগ্রেশন দেখুন →","1. MCP ক্লায়েন্ট বেছে নিন","ক্লায়েন্টের MCP, কানেক্টর, টুল বা ইন্টিগ্রেশন সেটিংস খুলুন।","2. রিমোট সার্ভার যোগ করুন","MCP এন্ডপয়েন্ট পেস্ট করে Poly-Glot নামে সংরক্ষণ করুন।","3. টুল অনুমোদন ও ব্যবহার করুন","অনুমতি দিয়ে টেমপ্লেট খুঁজুন, প্রম্পট তৈরি করুন, তুলনা প্রস্তুত করুন এবং অন্যান্য MCP টুল ব্যবহার করুন।"],"TR":["Poly-Glot'u desteklenen MCP istemcilerine bağlayın","Bu dizinler aynı canlı Poly-Glot MCP sunucusunu listeler. Uyumlu bir istemciye aşağıdaki Streamable HTTP URL'sini ekleyin, Poly-Glot adını verin ve araç erişimine izin verin. Her dizin için ayrı sunucu gerekmez.","MCP entegrasyonlarını keşfet →","1. MCP istemcini seç","İstemcinin MCP, Bağlayıcılar, Araçlar veya Entegrasyonlar ayarlarını açın.","2. Uzak sunucuyu ekle","MCP uç noktasını yapıştırıp Poly-Glot olarak kaydedin.","3. Araçları onayla ve kullan","Erişime izin verin; şablon arayın, istem oluşturun, karşılaştırma hazırlayın ve diğer MCP araçlarını kullanın."],"PL":["Połącz Poly-Glot z obsługiwanymi klientami MCP","Te katalogi zawierają ten sam produkcyjny serwer MCP Poly-Glot. W zgodnym kliencie dodaj poniższy adres Streamable HTTP, nazwij połączenie Poly-Glot i zezwól na używanie narzędzi. Nie potrzeba osobnego serwera dla każdego katalogu.","Poznaj integracje MCP →","1. Wybierz klienta MCP","Otwórz ustawienia MCP, konektorów, narzędzi lub integracji klienta.","2. Dodaj serwer zdalny","Wklej adres MCP i zapisz go jako Poly-Glot.","3. Zezwól na narzędzia i korzystaj z nich","Zezwól na dostęp, wyszukuj szablony, twórz prompty, przygotowuj porównania i korzystaj z innych narzędzi MCP."],"SV":["Anslut Poly-Glot från kompatibla MCP-klienter","Dessa kataloger listar samma Poly-Glot MCP-server i produktion. Lägg till Streamable HTTP-adressen nedan i en kompatibel klient, döp den till Poly-Glot och godkänn verktygsåtkomst. Du behöver inte en server per katalog.","Utforska MCP-integrationer →","1. Välj din MCP-klient","Öppna klientens inställningar för MCP, anslutningar, verktyg eller integrationer.","2. Lägg till fjärrservern","Klistra in MCP-adressen och spara den som Poly-Glot.","3. Godkänn och använd verktygen","Tillåt åtkomst, sök mallar, bygg promptar, förbered jämförelser och använd övriga MCP-verktyg."],"NO":["Koble Poly-Glot til støttede MCP-klienter","Disse katalogene viser den samme Poly-Glot MCP-serveren i produksjon. Legg til Streamable HTTP-adressen nedenfor i en kompatibel klient, kall den Poly-Glot og godkjenn verktøytilgang. Du trenger ikke en egen server per katalog.","Utforsk MCP-integrasjoner →","1. Velg MCP-klient","Åpne klientens innstillinger for MCP, tilkoblinger, verktøy eller integrasjoner.","2. Legg til ekstern server","Lim inn MCP-endepunktet og lagre som Poly-Glot.","3. Godkjenn og bruk verktøy","Tillat tilgang, søk etter maler, bygg prompter, forbered sammenligninger og bruk andre MCP-verktøy."],"DA":["Forbind Poly-Glot til understøttede MCP-klienter","Disse kataloger viser den samme Poly-Glot MCP-server i produktion. Tilføj Streamable HTTP-adressen nedenfor i en kompatibel klient, navngiv den Poly-Glot og godkend adgang til værktøjer. Ingen særskilt server kræves for hver katalog.","Udforsk MCP-integrationer →","1. Vælg din MCP-klient","Åbn klientens MCP-, connector-, værktøjs- eller integrationsindstillinger.","2. Tilføj fjernserveren","Indsæt MCP-endpointet og gem det som Poly-Glot.","3. Godkend og brug værktøjerne","Tillad adgang, søg efter skabeloner, byg prompts, forbered sammenligninger og brug andre MCP-værktøjer."],"FI":["Yhdistä Poly-Glot tuettuihin MCP-asiakasohjelmiin","Näissä hakemistoissa on sama Poly-Glotin tuotantokäytössä oleva MCP-palvelin. Lisää yhteensopivaan asiakasohjelmaan alla oleva Streamable HTTP -osoite, nimeä se Poly-Glotiksi ja salli työkalujen käyttö. Erillistä palvelinta ei tarvita.","Tutustu MCP-integraatioihin →","1. Valitse MCP-asiakasohjelma","Avaa MCP-, liitin-, työkalu- tai integraatioasetukset.","2. Lisää etäpalvelin","Liitä MCP-päätepiste ja tallenna se nimellä Poly-Glot.","3. Hyväksy ja käytä työkaluja","Salli käyttö, hae malleja, luo kehotteita, valmistele vertailuja ja käytä muita MCP-työkaluja."],"EL":["Συνδέστε το Poly-Glot σε υποστηριζόμενους πελάτες MCP","Αυτοί οι κατάλογοι εμφανίζουν τον ίδιο διακομιστή MCP παραγωγής του Poly-Glot. Προσθέστε τη διεύθυνση Streamable HTTP σε συμβατό πελάτη, ονομάστε τον Poly-Glot και επιτρέψτε την πρόσβαση στα εργαλεία. Δεν απαιτείται ξεχωριστός διακομιστής.","Εξερευνήστε τις ενσωματώσεις MCP →","1. Επιλέξτε πελάτη MCP","Ανοίξτε τις ρυθμίσεις MCP, συνδέσεων, εργαλείων ή ενσωματώσεων.","2. Προσθέστε απομακρυσμένο διακομιστή","Επικολλήστε το τελικό σημείο MCP και αποθηκεύστε το ως Poly-Glot.","3. Εγκρίνετε και χρησιμοποιήστε τα εργαλεία","Επιτρέψτε την πρόσβαση, βρείτε πρότυπα, δημιουργήστε προτροπές, προετοιμάστε συγκρίσεις και χρησιμοποιήστε άλλα εργαλεία MCP."],"HE":["חברו את Poly-Glot ללקוחות MCP נתמכים","הספריות האלה מציגות את אותו שרת MCP הפעיל של Poly-Glot. הוסיפו ללקוח תואם את כתובת Streamable HTTP שלמטה, תנו לחיבור את השם Poly-Glot ואשרו גישה לכלים. אין צורך בשרת נפרד לכל ספרייה.","לגלות שילובי MCP →","1. בחרו לקוח MCP","פתחו את הגדרות MCP, המחברים, הכלים או השילובים בלקוח.","2. הוסיפו שרת מרוחק","הדביקו את כתובת MCP ושמרו אותה בשם Poly-Glot.","3. אשרו והשתמשו בכלים","אפשרו גישה, חפשו תבניות, צרו פרומפטים, הכינו השוואות והשתמשו בכלי MCP נוספים."],"ID":["Hubungkan Poly-Glot dari klien MCP yang didukung","Direktori ini mencantumkan server MCP produksi Poly-Glot yang sama. Pada klien yang kompatibel, tambahkan URL Streamable HTTP di bawah, beri nama Poly-Glot, lalu izinkan akses alat. Tidak perlu server terpisah untuk tiap direktori.","Jelajahi integrasi MCP →","1. Pilih klien MCP","Buka pengaturan MCP, Konektor, Alat, atau Integrasi pada klien.","2. Tambahkan server jarak jauh","Tempel endpoint MCP dan simpan sebagai Poly-Glot.","3. Izinkan dan gunakan alat","Izinkan akses, cari templat, buat prompt, siapkan perbandingan, dan gunakan alat MCP lainnya."],"MS":["Sambungkan Poly-Glot melalui klien MCP yang disokong","Direktori ini menyenaraikan pelayan MCP pengeluaran Poly-Glot yang sama. Dalam klien serasi, tambah URL Streamable HTTP di bawah, namakannya Poly-Glot dan benarkan akses alat. Pelayan berasingan tidak diperlukan.","Terokai integrasi MCP →","1. Pilih klien MCP","Buka tetapan MCP, Penyambung, Alat atau Integrasi klien.","2. Tambah pelayan jauh","Tampal titik akhir MCP dan simpan sebagai Poly-Glot.","3. Benarkan dan guna alat","Benarkan akses, cari templat, bina prompt, sediakan perbandingan dan gunakan alat MCP lain."],"TH":["เชื่อมต่อ Poly-Glot จากไคลเอนต์ MCP ที่รองรับ","ไดเรกทอรีเหล่านี้แสดงเซิร์ฟเวอร์ MCP ของ Poly-Glot ตัวเดียวกัน ในไคลเอนต์ที่รองรับ ให้เพิ่ม URL Streamable HTTP ด้านล่าง ตั้งชื่อ Poly-Glot และอนุญาตให้ใช้เครื่องมือ ไม่จำเป็นต้องมีเซิร์ฟเวอร์แยกสำหรับแต่ละไดเรกทอรี","สำรวจการเชื่อมต่อ MCP →","1. เลือกไคลเอนต์ MCP","เปิดการตั้งค่า MCP ตัวเชื่อมต่อ เครื่องมือ หรือการผสานรวมของไคลเอนต์","2. เพิ่มเซิร์ฟเวอร์ระยะไกล","วาง MCP endpoint แล้วบันทึกชื่อ Poly-Glot","3. อนุญาตและใช้เครื่องมือ","อนุญาตการเข้าถึง ค้นหาเทมเพลต สร้างพรอมป์ เตรียมการเปรียบเทียบ และใช้เครื่องมือ MCP อื่น ๆ"],"VI":["Kết nối Poly-Glot từ các ứng dụng MCP được hỗ trợ","Những danh mục này đều giới thiệu cùng một máy chủ MCP Poly-Glot đang hoạt động. Trong ứng dụng tương thích, thêm URL Streamable HTTP bên dưới, đặt tên Poly-Glot và cấp quyền cho công cụ. Không cần máy chủ riêng cho từng danh mục.","Khám phá tích hợp MCP →","1. Chọn ứng dụng MCP","Mở cài đặt MCP, Trình kết nối, Công cụ hoặc Tích hợp của ứng dụng.","2. Thêm máy chủ từ xa","Dán điểm cuối MCP và lưu với tên Poly-Glot.","3. Cấp quyền và sử dụng công cụ","Cho phép truy cập, tìm mẫu, tạo prompt, chuẩn bị so sánh và dùng những công cụ MCP khác."],"UK":["Підключіть Poly-Glot у сумісних MCP-клієнтах","Ці каталоги показують той самий робочий MCP-сервер Poly-Glot. У сумісному клієнті додайте адресу Streamable HTTP нижче, назвіть підключення Poly-Glot та дозвольте доступ до інструментів. Окремий сервер для кожного каталогу не потрібен.","Переглянути інтеграції MCP →","1. Виберіть MCP-клієнт","Відкрийте налаштування MCP, конекторів, інструментів або інтеграцій.","2. Додайте віддалений сервер","Вставте адресу MCP і збережіть її як Poly-Glot.","3. Дозвольте використовувати інструменти","Надайте доступ, шукайте шаблони, створюйте запити, готуйте порівняння й користуйтеся іншими інструментами MCP."],"CS":["Připojte Poly-Glot z podporovaných klientů MCP","Tyto katalogy uvádějí stejný produkční server MCP Poly-Glot. V kompatibilním klientovi přidejte níže uvedenou adresu Streamable HTTP, pojmenujte ji Poly-Glot a povolte přístup k nástrojům. Pro každý katalog není třeba zvláštní server.","Prozkoumat integrace MCP →","1. Vyberte klienta MCP","Otevřete nastavení MCP, konektorů, nástrojů nebo integrací klienta.","2. Přidejte vzdálený server","Vložte endpoint MCP a uložte jej jako Poly-Glot.","3. Povolte a používejte nástroje","Povolte přístup, hledejte šablony, vytvářejte prompty, připravujte porovnání a používejte další nástroje MCP."],"RO":["Conectează Poly-Glot din clienți MCP compatibili","Aceste directoare listează același server MCP Poly-Glot de producție. Într-un client compatibil, adaugă adresa Streamable HTTP de mai jos, denumește-l Poly-Glot și aprobă accesul la instrumente. Nu este necesar alt server pentru fiecare director.","Explorează integrările MCP →","1. Alege clientul MCP","Deschide setările MCP, Conectori, Instrumente sau Integrări ale clientului.","2. Adaugă serverul la distanță","Lipește punctul final MCP și salvează-l ca Poly-Glot.","3. Aprobă și folosește instrumentele","Permite accesul, caută șabloane, creează prompturi, pregătește comparații și folosește celelalte instrumente MCP."],"HU":["Csatlakoztassa a Poly-Glotot támogatott MCP-kliensekkel","Ezek a könyvtárak ugyanazt az éles Poly-Glot MCP-kiszolgálót listázzák. Kompatibilis kliensben adja hozzá az alábbi Streamable HTTP-címet, nevezze el Poly-Glotnak, és engedélyezze az eszközhozzáférést. Nincs szükség külön kiszolgálóra.","MCP-integrációk megtekintése →","1. Válasszon MCP-klienst","Nyissa meg a kliens MCP-, csatlakozó-, eszköz- vagy integrációs beállításait.","2. Adjon hozzá távoli szervert","Illessze be az MCP-végpontot, és mentse Poly-Glot néven.","3. Engedélyezze és használja az eszközöket","Engedélyezze a hozzáférést, keressen sablonokat, készítsen promptokat, állítson össze összehasonlításokat és használja a többi MCP-eszközt."],"SK":["Pripojte Poly-Glot cez podporovaných klientov MCP","Tieto adresáre uvádzajú ten istý produkčný server MCP Poly-Glot. V kompatibilnom klientovi pridajte nižšie uvedenú adresu Streamable HTTP, pomenujte ju Poly-Glot a povoľte prístup k nástrojom. Nie je potrebný samostatný server pre každý adresár.","Preskúmať integrácie MCP →","1. Vyberte klienta MCP","Otvorte nastavenia MCP, konektorov, nástrojov alebo integrácií klienta.","2. Pridajte vzdialený server","Vložte endpoint MCP a uložte ho ako Poly-Glot.","3. Povoľte a používajte nástroje","Povoľte prístup, vyhľadávajte šablóny, vytvárajte prompty, pripravujte porovnania a používajte ďalšie MCP nástroje."],"HR":["Povežite Poly-Glot s podržanim MCP klijentima","Ovi imenici navode isti produkcijski Poly-Glot MCP poslužitelj. U kompatibilnom klijentu dodajte donji Streamable HTTP URL, nazovite vezu Poly-Glot i dopustite pristup alatima. Ne treba zaseban poslužitelj za svaki imenik.","Istražite MCP integracije →","1. Odaberite MCP klijent","Otvorite postavke za MCP, poveznike, alate ili integracije.","2. Dodajte udaljeni poslužitelj","Zalijepite MCP adresu i spremite je kao Poly-Glot.","3. Dopustite i koristite alate","Dopustite pristup, tražite predloške, izrađujte upite, pripremajte usporedbe i koristite ostale MCP alate."],"CA":["Connecta Poly-Glot des de clients MCP compatibles","Aquests directoris inclouen el mateix servidor MCP de producció de Poly-Glot. En un client compatible, afegeix l’URL Streamable HTTP, anomena'l Poly-Glot i aprova l’accés a les eines. No cal un servidor diferent per a cada directori.","Explora les integracions MCP →","1. Tria el client MCP","Obre la configuració MCP, Connectors, Eines o Integracions del client.","2. Afegeix el servidor remot","Enganxa el punt final MCP i desa'l com a Poly-Glot.","3. Aprova i utilitza les eines","Permet l'accés, cerca plantilles, crea prompts, prepara comparacions i fes servir les altres eines MCP."],"AF":["Koppel Poly-Glot aan ondersteunde MCP-kliënte","Hierdie gidse lys dieselfde produksie-Poly-Glot MCP-bediener. Voeg die Streamable HTTP-adres hieronder by ’n versoenbare kliënt, noem dit Poly-Glot en keur toegang tot gereedskap goed. Jy het nie ’n afsonderlike bediener vir elke gids nodig nie.","Verken MCP-integrasies →","1. Kies jou MCP-kliënt","Maak die kliënt se MCP-, verbindings-, gereedskap- of integrasie-instellings oop.","2. Voeg die afstandbediener by","Plak die MCP-eindpunt en stoor dit as Poly-Glot.","3. Laat gereedskap toe en gebruik dit","Laat toegang toe, soek sjablone, bou aansporings, berei vergelykings voor en gebruik ander MCP-gereedskap."],"SW":["Unganisha Poly-Glot na wateja wa MCP wanaotumika","Saraka hizi zinaonyesha seva ileile ya uzalishaji ya Poly-Glot MCP. Katika mteja anayeendana, ongeza URL ya Streamable HTTP hapa chini, ipe jina Poly-Glot na ruhusu zana. Huhitaji seva tofauti kwa kila saraka.","Chunguza miunganisho ya MCP →","1. Chagua mteja wa MCP","Fungua mipangilio ya MCP, viunganishi, zana au miunganisho ya mteja.","2. Ongeza seva ya mbali","Bandika URL ya MCP na uihifadhi kama Poly-Glot.","3. Ruhusu na utumie zana","Ruhusu ufikiaji, tafuta violezo, tengeneza prompts, andaa ulinganisho na tumia zana nyingine za MCP."],"HA":["Haɗa Poly-Glot da MCP clients masu dacewa","Waɗannan kundin suna nuna sabar Poly-Glot MCP ɗaya ta aiki. A cikin MCP client mai dacewa, ƙara adireshin Streamable HTTP na ƙasa, kira shi Poly-Glot sannan ba da izinin kayan aiki. Ba sai an yi sabar dabam ga kowane kundi ba.","Duba haɗin MCP →","1. Zaɓi MCP client","Buɗe saitunan MCP, masu haɗawa, kayan aiki ko haɗin kai a client.","2. Ƙara sabar nesa","Manna adireshin MCP kuma ajiye shi da sunan Poly-Glot.","3. Amince kuma yi amfani da kayan aiki","Ba da izini, bincika samfuran umarni, gina prompts, shirya kwatance da amfani da sauran kayan MCP."],"AM":["Poly-Glotን ከሚደገፉ MCP ደንበኞች ጋር ያገናኙ","እነዚህ ማውጫዎች ተመሳሳዩን የPoly-Glot MCP የምርት ሰርቨር ያሳያሉ። በሚስማማ ደንበኛ ውስጥ ከታች ያለውን Streamable HTTP URL ያክሉ፣ Poly-Glot ብለው ይሰይሙት እና የመሳሪያዎችን ፈቃድ ይስጡ። ለእያንዳንዱ ማውጫ የተለየ ሰርቨር አያስፈልግም።","የMCP ውህደቶችን ይመልከቱ →","1. MCP ደንበኛን ይምረጡ","የMCP፣ አገናኞች፣ መሳሪያዎች ወይም ውህደቶች ቅንብሮችን ይክፈቱ።","2. የርቀት ሰርቨር ያክሉ","የMCP አድራሻን ይለጥፉ እና Poly-Glot ብለው ያስቀምጡ።","3. ፈቅዱ እና መሳሪያዎችን ይጠቀሙ","ፈቃድ ይስጡ፣ አብነቶችን ይፈልጉ፣ ፕሮምፕቶችን ይገንቡ፣ ማነጻጸሪያዎችን ያዘጋጁ እና ሌሎች MCP መሳሪያዎችን ይጠቀሙ።"]};
var MCP_EN_TEXT=["Connect Poly-Glot from supported MCP clients","The listings below are discovery surfaces for the same production Poly-Glot MCP server. You do not need a different server for each directory. Supported means the client supports a remote Streamable HTTP MCP server like Poly-Glot's production endpoint. In a supported client, add the production endpoint below, name it Poly-Glot, then approve tool access when prompted.","Explore MCP integrations →","1. Choose your MCP client","Open the client's MCP, Connectors, Tools, or Integrations settings.","2. Add the remote server","Paste the Poly-Glot MCP endpoint and save it as Poly-Glot.","3. Approve & use the tools","Allow tool access, then search templates, build prompts, prepare comparisons, and use the available Poly-Glot MCP tools."];
var mcpNodes=null,mcpMarkup=[];
function localizeMcp(code){
 var root=document.getElementById("connect");if(!root)return;
 if(!mcpNodes){mcpNodes=MCP_EN_TEXT.map(function(t){return Array.from(root.querySelectorAll("div,p,a")).find(function(el){return norm(el.textContent)===norm(t)&&el.children.length<3;})||null;});mcpNodes.forEach(function(n,i){mcpMarkup[i]=n?n.innerHTML:"";});}
 var values=MCP_LOCALES[code]||MCP_LOCALES.EN;
 mcpNodes.forEach(function(n,i){if(!n)return;if(code==="EN"){if(n.innerHTML!==mcpMarkup[i])n.innerHTML=mcpMarkup[i];return;}if(n.textContent!==values[i])n.textContent=values[i];});
}

var FAQ_EXTRA={"EN":["After the 3-day trial:","What remains free after the 3-day trial?","How many MCP tools are available?","Poly-Glot offers 15 MCP tools for template search, prompt building, Compare Mode, language detection, translation, transcription, subscription status, workspace access, and Bring Your Own Model."],"ES":["Después de los 3 días de prueba:","¿Qué sigue siendo gratis después de la prueba de 3 días?","¿Cuántas herramientas MCP hay disponibles?","Poly-Glot ofrece 15 herramientas MCP para buscar plantillas, crear prompts, comparar IA, detectar idiomas, traducir, transcribir, consultar suscripciones, abrir el espacio de trabajo y conectar tus propios modelos."],"FR":["Après l’essai de 3 jours :","Qu’est-ce qui reste gratuit après l’essai de 3 jours ?","Combien d’outils MCP sont disponibles ?","Poly-Glot propose 15 outils MCP pour rechercher des modèles, créer des prompts, comparer les IA, détecter les langues, traduire, transcrire, consulter l’abonnement, ouvrir l’espace de travail et utiliser vos propres modèles."],"DE":["Nach der 3-tägigen Testphase:","Was bleibt nach der 3-tägigen Testphase kostenlos?","Wie viele MCP-Tools gibt es?","Poly-Glot bietet 15 MCP-Tools für Vorlagensuche, Prompt-Erstellung, KI-Vergleiche, Spracherkennung, Übersetzung, Transkription, Abostatus, Workspace-Zugriff und eigene Modelle."],"IT":["Dopo i 3 giorni di prova:","Cosa rimane gratuito dopo i 3 giorni di prova?","Quanti strumenti MCP sono disponibili?","Poly-Glot offre 15 strumenti MCP per cercare modelli, creare prompt, confrontare IA, rilevare lingue, tradurre, trascrivere, controllare l’abbonamento, aprire lo spazio di lavoro e usare modelli propri."],"PT":["Após os 3 dias de teste:","O que continua grátis após o teste de 3 dias?","Quantas ferramentas MCP estão disponíveis?","O Poly-Glot oferece 15 ferramentas MCP para buscar modelos, criar prompts, comparar IAs, detectar idiomas, traduzir, transcrever, consultar assinaturas, abrir o workspace e usar modelos próprios."],"NL":["Na de proefperiode van 3 dagen:","Wat blijft gratis na de proefperiode van 3 dagen?","Hoeveel MCP-tools zijn beschikbaar?","Poly-Glot biedt 15 MCP-tools voor het zoeken van sjablonen, maken van prompts, AI-vergelijkingen, taaldetectie, vertaling, transcriptie, abonnementsstatus, de werkruimte en eigen modellen."],"RU":["После 3-дневного пробного периода:","Что остаётся бесплатным после 3-дневного периода?","Сколько инструментов MCP доступно?","Poly-Glot предлагает 15 инструментов MCP: поиск шаблонов, создание запросов, сравнение ИИ, определение языка, перевод, расшифровка аудио, проверка подписки, рабочая область и собственные модели."],"ZH":["3 天试用结束后：","3 天试用后哪些功能仍免费？","有多少个 MCP 工具？","Poly-Glot 提供 15 个 MCP 工具，用于搜索模板、构建提示词、AI 对比、语言检测、翻译、音频转写、订阅查询、工作区访问和自定义模型。"],"ZH_TW":["3 天試用結束後：","3 天試用後哪些功能仍免費？","有多少個 MCP 工具？","Poly-Glot 提供 15 個 MCP 工具，可搜尋範本、建立提示詞、比較 AI、偵測語言、翻譯、語音轉寫、查詢訂閱、開啟工作區及使用自訂模型。"],"JA":["3 日間のトライアル終了後：","3 日間のトライアル後も無料で使える機能は？","MCP ツールはいくつありますか？","Poly-Glot には、テンプレート検索、プロンプト作成、AI 比較、言語検出、翻訳、文字起こし、契約状況の確認、ワークスペース操作、独自モデル向けの 15 の MCP ツールがあります。"],"KO":["3일 무료 체험 후:","3일 체험 후에도 무료로 사용할 수 있는 기능은?","MCP 도구는 몇 개 있나요?","Poly-Glot은 템플릿 검색, 프롬프트 작성, AI 비교, 언어 감지, 번역, 음성 전사, 구독 상태, 작업 공간 열기 및 사용자 모델을 위한 15개 MCP 도구를 제공합니다."],"AR":["بعد التجربة المجانية لمدة 3 أيام:","ما الذي يبقى مجانيًا بعد تجربة 3 أيام؟","كم عدد أدوات MCP المتاحة؟","يوفر Poly-Glot خمس عشرة أداة MCP للبحث عن القوالب وإنشاء المطالبات ومقارنة نماذج الذكاء الاصطناعي واكتشاف اللغات والترجمة والتفريغ الصوتي وحالة الاشتراك وفتح مساحة العمل واستخدام نماذجك الخاصة."],"HI":["3-दिन के ट्रायल के बाद:","3-दिन के ट्रायल के बाद क्या मुफ्त रहता है?","कितने MCP टूल उपलब्ध हैं?","Poly-Glot में टेम्पलेट खोज, प्रॉम्प्ट निर्माण, AI तुलना, भाषा पहचान, अनुवाद, ऑडियो ट्रांसक्रिप्शन, सदस्यता स्थिति, कार्यक्षेत्र और अपने मॉडल के लिए 15 MCP टूल हैं।"],"BN":["৩ দিনের ট্রায়ালের পর:","৩ দিনের ট্রায়ালের পর কী কী বিনামূল্যে থাকবে?","কতটি MCP টুল উপলব্ধ?","Poly-Glot-এ টেমপ্লেট খোঁজা, প্রম্পট তৈরি, AI তুলনা, ভাষা শনাক্তকরণ, অনুবাদ, অডিও ট্রান্সক্রিপশন, সাবস্ক্রিপশন, কর্মক্ষেত্র ও নিজস্ব মডেলের জন্য ১৫টি MCP টুল রয়েছে।"],"TR":["3 günlük deneme sonrasında:","3 günlük denemeden sonra neler ücretsiz kalır?","Kaç MCP aracı mevcut?","Poly-Glot; şablon arama, istem oluşturma, AI karşılaştırma, dil algılama, çeviri, ses yazıya dökme, abonelik bilgisi, çalışma alanı ve kendi modelleriniz için 15 MCP aracı sunar."],"PL":["Po 3-dniowym okresie próbnym:","Co pozostaje bezpłatne po 3-dniowym okresie próbnym?","Ile narzędzi MCP jest dostępnych?","Poly-Glot oferuje 15 narzędzi MCP do szukania szablonów, tworzenia promptów, porównywania AI, rozpoznawania języka, tłumaczeń, transkrypcji, sprawdzania subskrypcji, pracy w aplikacji i obsługi własnych modeli."],"SV":["Efter den 3 dagar långa provperioden:","Vad är fortsatt gratis efter 3 dagars provperiod?","Hur många MCP-verktyg finns?","Poly-Glot har 15 MCP-verktyg för mallsökning, promptbygge, AI-jämförelse, språkigenkänning, översättning, transkribering, abonnemang, arbetsyta och egna modeller."],"NO":["Etter prøveperioden på 3 dager:","Hva er fortsatt gratis etter 3 dagers prøveperiode?","Hvor mange MCP-verktøy finnes?","Poly-Glot tilbyr 15 MCP-verktøy for malsøk, promptbygging, AI-sammenligning, språkgjenkjenning, oversettelse, transkripsjon, abonnementsstatus, arbeidsområde og egne modeller."],"DA":["Efter prøveperioden på 3 dage:","Hvad er fortsat gratis efter prøveperioden på 3 dage?","Hvor mange MCP-værktøjer er tilgængelige?","Poly-Glot har 15 MCP-værktøjer til skabelonsøgning, promptopbygning, AI-sammenligning, sprogregistrering, oversættelse, transskription, abonnement, arbejdsområde og egne modeller."],"FI":["3 päivän kokeilujakson jälkeen:","Mikä on ilmaista 3 päivän kokeilujakson jälkeen?","Kuinka monta MCP-työkalua on saatavilla?","Poly-Glot tarjoaa 15 MCP-työkalua mallien hakuun, kehotteiden luontiin, tekoälyvertailuun, kielentunnistukseen, kääntämiseen, litterointiin, tilauksen tarkistamiseen, työtilaan ja omiin malleihin."],"EL":["Μετά τη δοκιμή 3 ημερών:","Τι παραμένει δωρεάν μετά τη δοκιμή 3 ημερών;","Πόσα εργαλεία MCP είναι διαθέσιμα;","Το Poly-Glot προσφέρει 15 εργαλεία MCP για αναζήτηση προτύπων, δημιουργία προτροπών, σύγκριση AI, αναγνώριση γλώσσας, μετάφραση, απομαγνητοφώνηση, συνδρομές, χώρο εργασίας και δικά σας μοντέλα."],"HE":["לאחר ניסיון של 3 ימים:","מה נשאר בחינם אחרי 3 ימי ניסיון?","כמה כלי MCP זמינים?","Poly-Glot מציע 15 כלי MCP לחיפוש תבניות, בניית הנחיות, השוואת מודלי AI, זיהוי שפה, תרגום, תמלול, מצב מנוי, סביבת עבודה ושימוש במודלים משלכם."],"ID":["Setelah uji coba 3 hari:","Apa yang tetap gratis setelah uji coba 3 hari?","Berapa alat MCP yang tersedia?","Poly-Glot menyediakan 15 alat MCP untuk mencari templat, membuat prompt, membandingkan AI, mendeteksi bahasa, menerjemahkan, mentranskripsikan, memeriksa langganan, membuka ruang kerja, dan memakai model sendiri."],"MS":["Selepas percubaan 3 hari:","Apa yang masih percuma selepas percubaan 3 hari?","Berapa banyak alat MCP tersedia?","Poly-Glot menawarkan 15 alat MCP untuk mencari templat, membina prompt, membandingkan AI, mengesan bahasa, menterjemah, transkripsi, status langganan, ruang kerja dan model sendiri."],"TH":["หลังทดลองใช้ฟรี 3 วัน:","หลังทดลองใช้ฟรี 3 วัน มีอะไรที่ยังใช้ฟรีได้บ้าง?","มีเครื่องมือ MCP กี่รายการ?","Poly-Glot มีเครื่องมือ MCP 15 รายการสำหรับค้นหาเทมเพลต สร้างพรอมป์ เปรียบเทียบ AI ตรวจจับภาษา แปลภาษา ถอดเสียง ดูสถานะสมัครสมาชิก เปิดพื้นที่ทำงาน และใช้โมเดลของคุณเอง"],"VI":["Sau thời gian dùng thử 3 ngày:","Những gì vẫn miễn phí sau 3 ngày dùng thử?","Có bao nhiêu công cụ MCP?","Poly-Glot cung cấp 15 công cụ MCP để tìm mẫu, tạo prompt, so sánh AI, phát hiện ngôn ngữ, dịch, phiên âm, kiểm tra thuê bao, mở không gian làm việc và sử dụng mô hình riêng."],"UK":["Після 3-денної пробної версії:","Що залишається безплатним після 3 днів пробного доступу?","Скільки інструментів MCP доступно?","Poly-Glot пропонує 15 інструментів MCP для пошуку шаблонів, створення запитів, порівняння ШІ, визначення мови, перекладу, транскрипції, перевірки підписки, робочого простору та власних моделей."],"CS":["Po 3denní zkušební době:","Co zůstává zdarma po 3denní zkušební době?","Kolik nástrojů MCP je k dispozici?","Poly-Glot nabízí 15 nástrojů MCP pro vyhledávání šablon, tvorbu promptů, porovnávání AI, detekci jazyka, překlad, přepis, stav předplatného, pracovní prostor a vlastní modely."],"RO":["După perioada de probă de 3 zile:","Ce rămâne gratuit după cele 3 zile de probă?","Câte instrumente MCP sunt disponibile?","Poly-Glot oferă 15 instrumente MCP pentru căutarea șabloanelor, generarea prompturilor, comparații AI, detectarea limbii, traducere, transcriere, abonamente, spațiul de lucru și modele proprii."],"HU":["A 3 napos próbaidő után:","Mi marad ingyenes a 3 napos próbaidő után?","Hány MCP-eszköz érhető el?","A Poly-Glot 15 MCP-eszközt kínál sablonkereséshez, promptépítéshez, AI-összehasonlításhoz, nyelvfelismeréshez, fordításhoz, átíráshoz, előfizetési állapothoz, munkaterülethez és saját modellekhez."],"SK":["Po 3-dňovej skúšobnej dobe:","Čo zostáva bezplatné po 3-dňovej skúšobnej dobe?","Koľko nástrojov MCP je dostupných?","Poly-Glot ponúka 15 MCP nástrojov na hľadanie šablón, tvorbu promptov, porovnávanie AI, rozpoznávanie jazyka, preklad, prepis, kontrolu predplatného, pracovný priestor a vlastné modely."],"HR":["Nakon trodnevnog probnog razdoblja:","Što ostaje besplatno nakon 3 dana probe?","Koliko je MCP alata dostupno?","Poly-Glot nudi 15 MCP alata za pretraživanje predložaka, izradu upita, usporedbu AI alata, prepoznavanje jezika, prijevod, transkripciju, status pretplate, radni prostor i vlastite modele."],"CA":["Després de la prova de 3 dies:","Què continua sent gratuït després de la prova de 3 dies?","Quantes eines MCP hi ha disponibles?","Poly-Glot ofereix 15 eines MCP per cercar plantilles, crear prompts, comparar IA, detectar idiomes, traduir, transcriure, consultar la subscripció, obrir l’espai de treball i utilitzar models propis."],"AF":["Ná die proeftydperk van 3 dae:","Wat bly gratis ná die 3-dae-proeftydperk?","Hoeveel MCP-gereedskap is beskikbaar?","Poly-Glot bied 15 MCP-gereedskap vir sjabloonsoektogte, aansporings, KI-vergelyking, taalherkenning, vertaling, transkripsie, intekeningstatus, werkruimte en jou eie modelle."],"SW":["Baada ya jaribio la siku 3:","Nini kinaendelea kuwa bure baada ya jaribio la siku 3?","Kuna zana ngapi za MCP?","Poly-Glot ina zana 15 za MCP za kutafuta violezo, kujenga maelekezo, kulinganisha AI, kutambua lugha, kutafsiri, kunukuu sauti, hali ya usajili, sehemu ya kazi na modeli zako mwenyewe."],"HA":["Bayan gwajin kwanaki 3:","Me zai ci gaba da zama kyauta bayan gwajin kwanaki 3?","Kayan aikin MCP nawa ne ake da su?","Poly-Glot na ba da kayan aikin MCP guda 15 don neman samfura, gina umarni, kwatanta AI, gano harshe, fassara, rubuta sauti, duba biyan kuɗi, buɗe wurin aiki da amfani da samfuranka."],"AM":["ከ3 ቀናት ሙከራ በኋላ፡","ከ3 ቀናት ሙከራ በኋላ ምን ነጻ ይቀራል?","ስንት MCP መሳሪያዎች አሉ?","Poly-Glot ለአብነት ፍለጋ፣ ፕሮምፕት ግንባታ፣ AI ማነጻጸር፣ ቋንቋ መለየት፣ ትርጉም፣ የድምጽ ጽሁፍ ማድረግ፣ ምዝገባ ሁኔታ፣ የስራ ቦታ እና የራስዎ ሞዴሎች 15 MCP መሳሪያዎችን ያቀርባል።"]};
